SELECT (SELECT count(*) FROM "Deal" d WHERE d."createdByUserId" IS NOT NULL) AS deals_with_creator, (SELECT count(*) FROM "Deal" d WHERE d."createdByUserId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "User" u WHERE u.id = d."createdByUserId")) AS creator_orphans, (SELECT count(*) FROM "DealAuditLog" a WHERE a."actorUserId" IS NOT NULL) AS audit_with_actor, (SELECT count(*) FROM "DealAuditLog" a WHERE a."actorUserId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "User" u WHERE u.id = a."actorUserId")) AS audit_actor_orphans
